fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    // Ensure all input slices have the same length
    let n = vals_1.len();
    debug_assert_eq!(vals_2.len(), n);
    debug_assert_eq!(conds_1.len(), n);
    debug_assert_eq!(conds_2.len(), n);

    // Prepare the output vector: clear any previous contents
    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        let a = vals_1[i];
        let b = vals_2[i];
        let c1 = conds_1[i];
        let c2 = conds_2[i];

        // By assumption, at least one of c1 or c2 is true.
        let out = if c1 && c2 {
            // Both true: take integer average
            (a + b) / 2
        } else if c1 {
            // Only the first is true
            a
        } else {
            // Only the second is true
            b
        };

        avgs.push(out);
    }
}

