        let v1: Vec<u64> = Vec::new();
        let v2: Vec<u64> = Vec::new();
        let c1: Vec<bool> = Vec::new();
        let c2: Vec<bool> = Vec::new();
        let mut out: Vec<u64> = vec![42; 5]; // pre-filled with garbage

        conditional_average(&v1, &v2, &c1, &c2, &mut out);
        assert!(out.is_empty());
