    #[test]
    fn test_conditional_average_various() {
        let v1 = vec![10, 20, 30, 40];
        let v2 = vec![1,  2,  3,  4];
        let c1 = vec![true,  true, false, true];
        let c2 = vec![true,  false, true, true];
        let mut out = Vec::new();

        // Index 0: both true  -> (10 + 1) / 2 = 5
        // Index 1: only c1    -> 20
        // Index 2: only c2    ->  3
        // Index 3: both true  -> (40 + 4) / 2 = 22
        conditional_average(&v1, &v2, &c1, &c2, &mut out);
        assert_eq!(out, vec![5, 20, 3, 22]);
    }

